import { View, Text, TextInput, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [name, setName] = useState("");
  const [sent, setSent] = useState(false);
  const empty = name.trim() === "";
  return (
    <View style={styles.screen}>
      <TextInput nativeID="name" style={styles.input} placeholder="Нэр"
        value={name} onChangeText={setName} />
      <Pressable nativeID="submit" style={styles.btn} onPress={() => setSent(true)}>
        {/* энд бичнэ үү: empty үед disabled ба бүдэг (styles.dim) болго */}
        <Text style={styles.btnText}>Илгээх</Text>
      </Pressable>
      {sent && <Text nativeID="done" style={styles.done}>Илгээлээ!</Text>}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 12, justifyContent: "center" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  btn: { backgroundColor: "#2563eb", padding: 14, borderRadius: 10, alignItems: "center" },
  dim: { opacity: 0.4 },
  btnText: { color: "#fff", fontWeight: "bold" },
  done: { color: "#16a34a", fontWeight: "600" },
});

registerRootComponent(App);

import { View, Text, TextInput, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [name, setName] = useState("");
  const [sent, setSent] = useState(false);
  const empty = name.trim() === "";
  return (
    <View style={styles.screen}>
      <TextInput nativeID="name" style={styles.input} placeholder="Нэр"
        value={name} onChangeText={setName} />
      <Pressable nativeID="submit" disabled={empty} style={[styles.btn, empty && styles.dim]} onPress={() => setSent(true)}>
        <Text style={styles.btnText}>Илгээх</Text>
      </Pressable>
      {sent && <Text nativeID="done" style={styles.done}>Илгээлээ!</Text>}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 12, justifyContent: "center" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  btn: { backgroundColor: "#2563eb", padding: 14, borderRadius: 10, alignItems: "center" },
  dim: { opacity: 0.4 },
  btnText: { color: "#fff", fontWeight: "bold" },
  done: { color: "#16a34a", fontWeight: "600" },
});

registerRootComponent(App);
